mapper.select:
SELECT CIO.IN_DATE ,CIO.IN_DTM ,CIO.OUT_DTM ,CASE CIO.IN_EQPM_NO WHEN 1 THEN '주차타워입구(1)' WHEN 3 THEN '야외주차장입구(3)' WHEN 5 THEN 'PS게이트입구(5)' WHEN 7 THEN 'HL게이트입구(7)' WHEN 9 THEN '후문입구(9)' ELSE CIO.IN_EQPM_NO || '' END AS IN_EQPM_NM ,CASE CIO.OUT_EQPM_NO WHEN 0 THEN '기록없음(0)' WHEN 2 THEN '주차타워출구(2)' WHEN 4 THEN '야외주차장출구(4)' WHEN 6 THEN 'PS게이트출구(6)' WHEN 10 THEN '후문출구(10)' ELSE CIO.OUT_EQPM_NO || '' END AS OUT_EQPM_NM ,CIO.CAR_NO ,CIO.USER_NAME ,CASE WHEN LENGTH(TRIM(CIO.IN_CAR_PIC_NAME)) > 1 THEN 'http://192.1.21.77/phms_ms/api/image/' || CIO.IN_DATE || '/' || CIO.IN_CAR_PIC_NAME ELSE '' END AS IN_CAR_PIC_URL , '이미지' AS PIC_URL FROM TB_CARINOUT CIO WHERE 1 = 1
AND SL.LOGTYP = #{LOGTYP}
${RANGE_SQL}
